  INST_lastSeen.dump_VCD(dt, backing.INST_lastSeen);
  INST_len.dump_VCD(dt, backing.INST_len);
  INST_lfsr.dump_VCD(dt, backing.INST_lfsr);
  INST_mode.dump_VCD(dt, backing.INST_mode);
  INST_n.dump_VCD(dt, backing.INST_n);
